class Solution:
    def canConvert(self, A: List[List[int]], B: List[List[int]]) -> int:
        n = len(A)
        D = [[A[i][j] ^ B[i][j] for j in range(n)] for i in range(n)]
        # Cell (i, j) with i, j < n-1 can only be fixed by the block whose top-left it is,
        # once everything above and to the left is already fixed.
        for i in range(n - 1):
            row, nxt = D[i], D[i + 1]
            for j in range(n - 1):
                if row[j]:
                    row[j] ^= 1; row[j + 1] ^= 1; nxt[j] ^= 1; nxt[j + 1] ^= 1
        return int(not any(D[n - 1]) and not any(D[i][n - 1] for i in range(n)))

