class Solution {
public:
    int canConvert(vector<vector<int>>& A, vector<vector<int>>& B) {
        int n = A.size();
        vector<vector<int>> D(n, vector<int>(n));
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) D[i][j] = A[i][j] ^ B[i][j];
        for (int i = 0; i + 1 < n; i++) for (int j = 0; j + 1 < n; j++)
            if (D[i][j]) { D[i][j] ^= 1; D[i][j + 1] ^= 1; D[i + 1][j] ^= 1; D[i + 1][j + 1] ^= 1; }
        for (int k = 0; k < n; k++) if (D[n - 1][k] || D[k][n - 1]) return 0;
        return 1;
    }
};

